// The app's client for the slop-haus API: application-specific glue over
// openapi-fetch and the types generated from the server's OpenAPI spec
// (../api_generated, regenerated by ../../generate_api_client.sh). Each operation keeps the name and signature components call it
// by, unwraps collection envelopes, and throws ApiError on failure. One
// file per resource holds its operations; apiClient is their merge, so
// callers keep using apiClient.x.
import { attachmentsApi } from "./attachments";
import { agentsApi } from "./agents";
import { compareApi } from "./compare";
import { conversationsApi } from "./conversations";
import { evalSetsApi } from "./eval_sets";
import { integrationsApi } from "./integrations";
import { landingApi } from "./landing";
import { proposalsApi } from "./proposals";
import { provisioningApi } from "./provisioning";
import { reportsApi } from "./reports";
import { sessionApi } from "./session";
import { settingsApi } from "./settings";
import { stewardApi } from "./steward";
import { ticketsApi } from "./tickets";

export * from "./types";
export type {
  CompareMeasure,
  ComparePair,
  CompareRequest,
  CompareResult,
  CompareRow,
  CompareSide,
  CompareSummary,
  CompareVerdicts,
} from "./compare";
export type {
  EvalSet,
  EvalSetBatch,
  EvalSetDefinition,
  EvalSetFilter,
  EvalSetRunResult,
} from "./eval_sets";
export type { LandingCapabilities, LandingEntry } from "./landing";
export type {
  DesiredAgent,
  DesiredAgentView,
  DesiredState,
  OwnRemoteControlSupervisor,
  OwnRemoteControlSupervisors,
  ProvisionSupervisor,
  UnmanagedSlot,
} from "./provisioning";
export {
  ApiError,
  BulkRefusedError,
  CSRF_HEADER,
  RoleInUseError,
  consentFetch,
  onApiFailure,
  onSignedOut,
  onTenantChanged,
  sessionWriteHeaders,
  type ApiFailure,
} from "./client";

export const apiClient = {
  ...sessionApi,
  ...ticketsApi,
  ...attachmentsApi,
  ...evalSetsApi,
  ...agentsApi,
  ...conversationsApi,
  ...settingsApi,
  ...integrationsApi,
  ...reportsApi,
  ...compareApi,
  ...proposalsApi,
  ...stewardApi,
  ...provisioningApi,
  ...landingApi,
};
